def separability_matrix(left_dim, right_dim, nested_corr):
    total = left_dim + right_dim
    mat = zeros_grid(total, total)
    for i in range(left_dim):
        mat[i][i] = 1
    for r in range(right_dim):
        for c in range(right_dim):
            if nested_corr[r][c] != 0:
                mat[left_dim + r][left_dim + c] = nested_corr[r][c]
    return mat
