def reconcile_balances(events: list) -> dict:
    bal = {}
    seen_events = set()
    for eid, acct, delta in events:
        if eid not in seen_events:
            seen_events.add(eid)
            a = normalize_acct(acct)
            bal[a] = bal.get(a, 0) + delta
    return dict(sorted(bal.items()))
