def has_permission(user_roles: list, role_parents: dict, role_perms: dict, required_perm: str) -> bool:
    visited = set()

    def traverse_role(r):
        if r in visited:
            return False
        visited.add(r)
        if required_perm in direct_perms(r, role_perms):
            return True
        for parent in role_parents.get(r, []):
            if traverse_role(parent):
                return True
        return False
    for r in user_roles:
        if traverse_role(r):
            return True
    return False
```

