def paginate_records(records: list, cursor_id, limit: int) -> dict:
    s = sort_by_id(records)
    if cursor_id is not None:
        s = [r for r in s if r['id'] > cursor_id]
    page = s[:limit]
    next_cursor = page[-1]['id'] if len(s) > limit else None
    return {'items': page, 'next_cursor': next_cursor}
