def summarize_latencies(samples: list, drop_outliers: bool=True) -> dict:
    if not samples:
        return {'count': 0, 'min': 0.0, 'max': 0.0, 'mean': 0.0}
    s = sorted(samples)
    if drop_outliers and len(s) >= 4:
        s.pop(0)
        s.pop(-1)
    return {'count': len(s), 'min': float(s[0]), 'max': float(s[-1]), 'mean': safe_mean(s)}
